css:
.fx-dwave .sec{position:relative;flex:1;display:grid;align-content:center;justify-items:center;text-align:center;gap:.8em;padding:5em 1.25em}
.fx-dwave .sec h2{font-size:clamp(1.8em,4vw,2.8em);max-width:16em}.fx-dwave .sec p{opacity:.75;max-width:44ch}
.fx-dwave .sec .k{font-size:.75em;font-weight:700;letter-spacing:.16em;text-transform:uppercase;opacity:.7}
.fx-dwave{display:flex;flex-direction:column;background:var(--surface)}
.fx-dwave .s1{background:var(--surface);padding-bottom:calc(5em + 4vw)}
.fx-dwave .s2{background:var(--primary);color:var(--on-primary);padding-bottom:calc(5em + 4vw)}
.fx-dwave .s3{background:color-mix(in srgb,var(--accent) 12%,var(--surface))}
.fx-dwave .wv{position:absolute;left:0;bottom:-1px;width:100%;height:clamp(48px,8vw,110px);overflow:hidden;line-height:0;z-index:2}
.fx-dwave .wv svg{position:absolute;left:0;bottom:0;width:200%;height:100%;animation:fxdw calc(14s/var(--speed)) linear infinite}
.fx-dwave .wv svg.back{animation-duration:calc(22s/var(--speed));animation-direction:reverse;opacity:.45}
.fx-dwave .w1 path{fill:var(--primary)}.fx-dwave .w2 path{fill:color-mix(in srgb,var(--accent) 12%,var(--surface))}
@keyframes fxdw{to{transform:translateX(-50%)}}
@media(prefers-reduced-motion:reduce){.fx-dwave .wv svg{animation:none}}
